import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/BackButton'
import type { Comment, Post } from '@/lib/types'

const API_URL = 'https://jsonplaceholder.typicode.com'
const REVALIDATE_SECONDS = 300 // 5 minutes

// Params not returned here are rendered on demand (replaces fallback: 'blocking')
export const dynamicParams = true

export async function generateStaticParams() {
  const posts: Post[] = await fetch(`${API_URL}/posts`, {
    next: { revalidate: 60 },
  }).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

async function fetchJson<T>(path: string): Promise<T> {
  // Identical fetch calls are memoized, so generateMetadata and the page share
  // a single request per render.
  const res = await fetch(`${API_URL}${path}`, {
    next: { revalidate: REVALIDATE_SECONDS },
  })
  if (!res.ok) {
    throw new Error(`Failed to fetch ${path}: ${res.status}`)
  }
  return res.json()
}

async function getPostWithComments(
  id: string
): Promise<{ post: Post; comments: Comment[] } | null> {
  try {
    const [post, comments] = await Promise.all([
      fetchJson<Post>(`/posts/${id}`),
      fetchJson<Comment[]>(`/posts/${id}/comments`),
    ])
    return { post, comments }
  } catch {
    return null
  }
}

export async function generateMetadata({
  params,
}: PageProps<'/blog/[id]'>): Promise<Metadata> {
  const { id } = await params
  const data = await getPostWithComments(id)
  if (!data) notFound()

  const { post } = data
  const description = post.body.substring(0, 160)

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPost({ params }: PageProps<'/blog/[id]'>) {
  const { id } = await params
  const data = await getPostWithComments(id)
  if (!data) notFound()

  const { post, comments } = data

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

