import type { NextRequest } from 'next/server'
import type { ApiPost, ApiPostInput } from '@/lib/types'

// Methods without an exported handler automatically respond with 405

export async function GET(
  _request: NextRequest,
  ctx: RouteContext<'/api/posts/[id]'>
) {
  const { id } = await ctx.params

  // Simulate fetching a single post
  const post: ApiPost = {
    id: parseInt(id),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(
  request: NextRequest,
  ctx: RouteContext<'/api/posts/[id]'>
) {
  const { id } = await ctx.params
  const { title, content }: ApiPostInput = await request
    .json()
    .catch(() => ({}))

  // Simulate updating a post
  const updatedPost: ApiPost = {
    id: parseInt(id),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(
  _request: NextRequest,
